function out = arm_G(q, P)
%ARM_G Gravity vector G(q)
%% AUTO-GENERATED by python/rehab_arm/dynamics_derive.py (SymPy Euler-Lagrange).
%% P = [L1 L2 c1 c2 m1 m2 mp r1 r2 g]
%#codegen
q1 = q(1); q2 = q(2); q3 = q(3);
L1 = P(1); L2 = P(2); c1 = P(3); c2 = P(4); m1 = P(5); m2 = P(6); mp = P(7); r1 = P(8); r2 = P(9); g = P(10); 
out = zeros(3,1);
t0 = L1.*cos(q2);
t1 = c1.*m1;
t2 = q2 + q3;
t3 = cos(t2);
t4 = L2.*mp;
t5 = c2.*m2;
t6 = L2.*t5;
t7 = L1.*sin(q2);
t8 = sin(t2);
t9 = g.*cos(q1);
out(1,1) = g.*(m2.*t0 + mp.*t0 + t0.*t1 + t3.*t4 + t3.*t6).*sin(q1);
out(2,1) = t9.*(m2.*t7 + mp.*t7 + t1.*t7 + t4.*t8 + t6.*t8);
out(3,1) = L2.*t8.*t9.*(mp + t5);
end
